import{_ as c,C as s,o as d,c as p,j as t,a,E as o,a8 as w}from"./chunks/framework.27XeWUA0.js";const n="/schedule-dashboard/thumbs/yt/JNexz3Tbiu8-640.webp",u="/schedule-dashboard/thumbs/yt/JNexz3Tbiu8-1280.webp",r="/schedule-dashboard/thumbs/yt/MwOYrNAX1Ig-640.webp",m="/schedule-dashboard/thumbs/yt/MwOYrNAX1Ig-1280.webp",i="/schedule-dashboard/thumbs/yt/v4AX5Uz23Go-640.webp",g="/schedule-dashboard/thumbs/yt/v4AX5Uz23Go-1280.webp",z=JSON.parse('{"title":"AI Digest · Mon 23 Nov 2026","description":"","frontmatter":{"aside":false,"outline":false},"headers":[],"params":{"date":"2026-11-23","routine":"digest"},"relativePath":"digest/2026-11-23.md","filePath":"digest/[date].md"}'),b={name:"digest/2026-11-23.md"},f=n+" 640w, "+u+" 1280w",v=r+" 640w, "+m+" 1280w",y=i+" 640w, "+g+" 1280w",k={id:"ai-digest-·-mon-23-nov-2026",tabindex:"-1"};function _(A,e,T,N,x,S){const l=s("Badge"),h=s("DayFilter");return d(),p("div",null,[t("h1",k,[e[0]||(e[0]=a("AI Digest · Mon 23 Nov 2026 ",-1)),o(l,{type:"tip",text:"3"}),e[1]||(e[1]=a()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#ai-digest-·-mon-23-nov-2026","aria-label":'Permalink to "AI Digest · Mon 23 Nov 2026 <Badge type="tip" text="3" />"'},"​",-1))]),e[3]||(e[3]=t("p",{class:"sub"},"AI Engineer + Better Stack daily digest — 23 Nov 2026 · run date Mon 23 Nov 2026 · 3 videos",-1)),e[4]||(e[4]=t("div",{class:"overview"},[t("p",null,[t("strong",null,"AI Engineer:"),a(" There is 1 new talk (23 Nov, 1:30 AM IST): Armin Ronacher of Earendil (Pi coding agent) on building the workshop before the software factory, 20 minutes. The theme is well-worn, but it's full of his own agent-usage data, so it's worth watching.")]),t("p",null,[t("strong",null,"Better Stack:"),a(` There are 2 new videos, both fresh ground and worth watching. The freshest (23 Nov, 3:00 AM IST) tests TanStack Redact's "70% smaller React" claim: bundles shrink, but typing gets slower on heavy UIs. The other trains a neural network from scratch on an ESP32-S3 microcontroller, in 18 seconds, and has it learn his own sounds in under a second.`)])],-1)),o(h),e[5]||(e[5]=w('<div class="grid cards2"><article class="it full" id="v-JNexz3Tbiu8" data-title="Build the Workshop Before the Software Factory — Armin Ronacher, Earendil" data-channel="AI Engineer" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=JNexz3Tbiu8" target="_blank" rel="noopener"><img src="'+n+'" srcset="'+f+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=JNexz3Tbiu8" target="_blank" rel="noopener">Build the Workshop Before the Software Factory — Armin Ronacher, Earendil</a></h3><div class="meta">AI Engineer · Armin Ronacher, Earendil (Pi coding agent) · uploaded 23 Nov, 1:30 AM IST · 19:56</div><div class="verdict v-worth"><b>Verdict:</b> worth watching — the topic is well-worn, but the 20 minutes are full of Ronacher&#39;s own usage data and practical habits you haven&#39;t seen in the earlier software-factory talks.</div><div class="repeat">🔁 Repeat: &#39;human-in-the-loop review&#39; — seen 52 times before. New here: Ronacher&#39;s own session data on how far he has stepped back, and his trick of having the agent write an executive summary before verification instead of reading the code.</div><div class="repeat">🔁 Repeat: &#39;software factory&#39; — seen 27 times before. New here: the counter-pitch (build the workshop first, then the factory) backed by his numbers: 141 projects started, only 10–15 still maintained.</div><div class="repeat">🔁 Repeat: &#39;harness engineering&#39; — seen 43 times before. New here: the claim that Pi&#39;s core harness hasn&#39;t changed in a year and still does far more, purely because the models improved.</div><div class="repeat">🔁 Repeat: &#39;decision models&#39; — seen 11 times before. New here: using cheap classifier models as the if-branches inside code-mode workflows, e.g. triaging 3,000 support tickets.</div><div class="repeat">🔁 Repeat: &#39;durable execution&#39; — seen 4 times before. New here: suspending agents and their sandboxes to wait out cheaper flex-scheduled tokens.</div><div class="sh">The models improved, the harness didn&#39;t</div><ul><li><strong>Same tools, much more power:</strong> Pi&#39;s core harness has the same tools as last December, yet it does far more because the models got better. Old harness tricks have mostly stopped mattering: his favourite plugin, PyAutoResearch (drive toward a goal like better performance), is no longer needed with current models. His own count of corrections per session dropped with each new model (<a href="https://www.youtube.com/watch?v=JNexz3Tbiu8&amp;t=103s" target="_blank" rel="noopener">1:43</a>–<a href="https://www.youtube.com/watch?v=JNexz3Tbiu8&amp;t=197s" target="_blank" rel="noopener">3:17</a>)</li><li><strong>Tasks now run 14 minutes:</strong> At the 90th percentile, an agent ran about 2.5 minutes per task with Opus 4.6 last December and now runs 14+ minutes. Current models also reach for Bash far more than any other tool, and code mode is slowly creeping up in his data (<a href="https://www.youtube.com/watch?v=JNexz3Tbiu8&amp;t=197s" target="_blank" rel="noopener">3:17</a>–<a href="https://www.youtube.com/watch?v=JNexz3Tbiu8&amp;t=287s" target="_blank" rel="noopener">4:47</a>)</li></ul><div class="sh">Human attention is the limit</div><ul><li><strong>Flat prompts, exploding agent time:</strong> He still sends a fairly flat 120–190 prompts a day, but agent run time went from less than his working day to many times it. He warns that GitHub and older websites are being hammered by agent traffic they weren&#39;t built for (<a href="https://www.youtube.com/watch?v=JNexz3Tbiu8&amp;t=287s" target="_blank" rel="noopener">4:47</a>–<a href="https://www.youtube.com/watch?v=JNexz3Tbiu8&amp;t=377s" target="_blank" rel="noopener">6:17</a>)</li><li><strong>141 projects started, 10–15 maintained:</strong> Repos he created keep climbing, but projects he commits to regularly have stayed at 10–15. A friend fully automated an open source project with an auto-review agent, then turned it off once he stopped caring and wanted the tokens for other work (<a href="https://www.youtube.com/watch?v=JNexz3Tbiu8&amp;t=377s" target="_blank" rel="noopener">6:17</a>–<a href="https://www.youtube.com/watch?v=JNexz3Tbiu8&amp;t=467s" target="_blank" rel="noopener">7:47</a>)</li><li><strong>Know when to push back:</strong> Agents are rewarded for finishing the goal, which easily produces a &quot;Simpson car&quot; of bolted-on features. He calls the difference &quot;true skill vs agent skill&quot;: his son, who isn&#39;t an engineer, sends him PRs through the same setup, and the quality gap is obvious (<a href="https://www.youtube.com/watch?v=JNexz3Tbiu8&amp;t=467s" target="_blank" rel="noopener">7:47</a>–<a href="https://www.youtube.com/watch?v=JNexz3Tbiu8&amp;t=602s" target="_blank" rel="noopener">10:02</a>)</li><li><strong>Executive summaries instead of reading code:</strong> Around 70% of the way through a session, before verification, he has the agent write a short executive summary and a typeset HTML page explaining what it did. That is how he keeps understanding his projects now that he often doesn&#39;t read the code (<a href="https://www.youtube.com/watch?v=JNexz3Tbiu8&amp;t=602s" target="_blank" rel="noopener">10:02</a>–<a href="https://www.youtube.com/watch?v=JNexz3Tbiu8&amp;t=692s" target="_blank" rel="noopener">11:32</a>)</li></ul><div class="sh">Toward excellent software</div><ul><li><strong>Uncontrolled growth and file formats:</strong> When every agent can implement any format, implementations drift. His example is a tar archive crafted so different tar implementations read it differently. Open protocols and shared file formats matter more than ever, and forking is replacing upstream collaboration in open source (<a href="https://www.youtube.com/watch?v=JNexz3Tbiu8&amp;t=692s" target="_blank" rel="noopener">11:32</a>–<a href="https://www.youtube.com/watch?v=JNexz3Tbiu8&amp;t=917s" target="_blank" rel="noopener">15:17</a>)</li><li><strong>Durable agents:</strong> Long-running overnight agents need to suspend, resume and restart themselves. That also lets them pause, sandbox included, while waiting on discounted flex-scheduled tokens that can take minutes to arrive (<a href="https://www.youtube.com/watch?v=JNexz3Tbiu8&amp;t=917s" target="_blank" rel="noopener">15:17</a>–<a href="https://www.youtube.com/watch?v=JNexz3Tbiu8&amp;t=1011s" target="_blank" rel="noopener">16:51</a>)</li><li><strong>Code mode plus classifiers:</strong> Following Cloudflare&#39;s idea, the agent gets JavaScript to call its tools, so the harness (Codex and Pi already support this) can run large batches of tool calls outside the context. Combined with cheap, fast classifier models as the decision points, it can triage something like 3,000 support requests in minutes instead of hours (<a href="https://www.youtube.com/watch?v=JNexz3Tbiu8&amp;t=1011s" target="_blank" rel="noopener">16:51</a>–<a href="https://www.youtube.com/watch?v=JNexz3Tbiu8&amp;t=1146s" target="_blank" rel="noopener">19:06</a>)</li></ul></div></article><article class="it full" id="v-MwOYrNAX1Ig" data-title="TanStack Just Shrunk React by 70%" data-channel="Better Stack" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=MwOYrNAX1Ig" target="_blank" rel="noopener"><img src="'+r+'" srcset="'+v+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">Better Stack</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=MwOYrNAX1Ig" target="_blank" rel="noopener">TanStack Just Shrunk React by 70%</a></h3><div class="meta">Better Stack · Better Stack · uploaded 23 Nov, 3:00 AM IST · 7:01</div><div class="verdict v-worth"><b>Verdict:</b> worth watching — a short, honest test: smaller bundles and faster loads, but slower typing on heavy UIs.</div><div class="repeat">🔁 Repeat: &#39;JS/TS ecosystem&#39; — seen 16 times before. New here: TanStack Redact itself, a React replacement for the browser, tested with real bundle and keystroke numbers.</div><div class="sh">What Redact is</div><ul><li><strong>Drop-in React for the browser:</strong> TanStack Redact replaces react and react-dom in the browser while you keep your normal React imports, components and hooks. You add one build plugin, and it works with TanStack Start, Vite, Next.js, Webpack and Rspack. On Next.js, real React still runs on the server and handles server components (<a href="https://www.youtube.com/watch?v=MwOYrNAX1Ig&amp;t=18s" target="_blank" rel="noopener">0:18</a>–<a href="https://www.youtube.com/watch?v=MwOYrNAX1Ig&amp;t=46s" target="_blank" rel="noopener">0:46</a>)</li><li><strong>The 70% claim holds for small apps:</strong> On a fresh Vite React starter, gzipped JS went from 66.8 KB (React 19) to 20.2 KB with Redact, or 12.9 KB with the &quot;nano&quot; preset. TanStack&#39;s own tests cut total client JS + CSS by 70.5% (Vite), 43% (TanStack Start) and 28.5% (Next.js). In his tests it saved about 46 KB no matter the app size, so the percentage shrinks as your app grows (<a href="https://www.youtube.com/watch?v=MwOYrNAX1Ig&amp;t=46s" target="_blank" rel="noopener">0:46</a>–<a href="https://www.youtube.com/watch?v=MwOYrNAX1Ig&amp;t=101s" target="_blank" rel="noopener">1:41</a>)</li><li><strong>How it gets small:</strong> A build-time alias swaps the imports. Redact drops React&#39;s concurrent scheduler and renders synchronously, so a heavy render can delay input. Build flags can strip context, suspense, memo or hydration, and deprecated APIs like findDOMNode are gone (<a href="https://www.youtube.com/watch?v=MwOYrNAX1Ig&amp;t=101s" target="_blank" rel="noopener">1:41</a>–<a href="https://www.youtube.com/watch?v=MwOYrNAX1Ig&amp;t=156s" target="_blank" rel="noopener">2:36</a>)</li><li><strong>Why not Preact:</strong> Preact&#39;s compat layer is smaller (11.2 KB vs Redact&#39;s 23.3 KB), but it has drifted from React 19. It lacks useActionState, useOptimistic and useFormStatus, and its useTransition pending state is always false. Tanner gave up after about five patches (<a href="https://www.youtube.com/watch?v=MwOYrNAX1Ig&amp;t=156s" target="_blank" rel="noopener">2:36</a>–<a href="https://www.youtube.com/watch?v=MwOYrNAX1Ig&amp;t=206s" target="_blank" rel="noopener">3:26</a>)</li></ul><div class="sh">Real-world results</div><ul><li><strong>Mixed production numbers:</strong> On Tanner&#39;s blog, JS dropped by a third and first paint was about 18% faster. On tanstack.com, JS only dropped about 5%, and server-component pages showed their main content 8–43% later. PostHog&#39;s coding agent measured a 3.6% saving with 33 of 95 sample test files failing, and concluded &quot;do not adopt now&quot; (<a href="https://www.youtube.com/watch?v=MwOYrNAX1Ig&amp;t=206s" target="_blank" rel="noopener">3:26</a>–<a href="https://www.youtube.com/watch?v=MwOYrNAX1Ig&amp;t=259s" target="_blank" rel="noopener">4:19</a>)</li><li><strong>His 20,000-order dashboard:</strong> With the CPU throttled 4×, the Redact build had no errors, 17% less JS and a 14% faster first paint. But the slowest keystroke in search went from 80 ms to 200 ms, and it was still 168 vs 200 ms with React&#39;s concurrent feature off. TanStack&#39;s own list benchmarks score React 100 and Redact 78 (<a href="https://www.youtube.com/watch?v=MwOYrNAX1Ig&amp;t=259s" target="_blank" rel="noopener">4:19</a>–<a href="https://www.youtube.com/watch?v=MwOYrNAX1Ig&amp;t=337s" target="_blank" rel="noopener">5:37</a>)</li><li><strong>Built by prompting:</strong> Tanner built the first version in &quot;one day of prompting with Claude&quot;, and it now passes 1,859 tests. In August he called it a &quot;slop fork&quot; of React on the Better Stack podcast. Now TanStack thinks it is worth maintaining (<a href="https://www.youtube.com/watch?v=MwOYrNAX1Ig&amp;t=337s" target="_blank" rel="noopener">5:37</a>–<a href="https://www.youtube.com/watch?v=MwOYrNAX1Ig&amp;t=421s" target="_blank" rel="noopener">7:01</a>)</li></ul></div></article><article class="it full" id="v-v4AX5Uz23Go" data-title="This Tiny Chip Trained Its Own AI in 18 Seconds" data-channel="Better Stack" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=v4AX5Uz23Go" target="_blank" rel="noopener"><img src="'+i+'" srcset="'+y+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">Better Stack</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=v4AX5Uz23Go" target="_blank" rel="noopener">This Tiny Chip Trained Its Own AI in 18 Seconds</a></h3><div class="meta">Better Stack · Andres, Better Stack · uploaded 22 Nov, 12:45 PM IST · 10:07</div><div class="verdict v-worth"><b>Verdict:</b> worth watching — a fun, concrete hardware demo with real numbers; a genuinely new angle (on-chip training) on the edge-AI topic.</div><div class="repeat">🔁 Repeat: &#39;edge / on-device AI&#39; — seen 4 times before. New here: the chip trains the network itself (backprop + Adam), not just inference, and learns new sounds in under a second.</div><div class="sh">The setup</div><ul><li><strong>Inspired by a laptop-trained experiment:</strong> Bill McCartney&#39;s post &quot;Neural nets on chips that &#39;can&#39;t do&#39; neural nets&quot; trains a small classifier (sine, square, chirp or noise from 32 sensor readings) on a laptop. It then runs the weights on 16 microcontrollers, down to an 8-bit PIC16 at about 2.3 decisions a second. Andres moved the training onto the chip (<a href="https://www.youtube.com/watch?v=v4AX5Uz23Go&amp;t=47s" target="_blank" rel="noopener">0:47</a>–<a href="https://www.youtube.com/watch?v=v4AX5Uz23Go&amp;t=97s" target="_blank" rel="noopener">1:37</a>)</li><li><strong>How small it is:</strong> The network goes 32 → 32 → 16 → 8 → 4, with 1,756 weights (about 7 KB). 80 Adam training steps add up to about 1.32 billion multiply-adds at 240 MHz (<a href="https://www.youtube.com/watch?v=v4AX5Uz23Go&amp;t=97s" target="_blank" rel="noopener">1:37</a>–<a href="https://www.youtube.com/watch?v=v4AX5Uz23Go&amp;t=152s" target="_blank" rel="noopener">2:32</a>)</li><li><strong>Memory is the real limit:</strong> Training needs about 28 KB for gradients and Adam state plus 128 KB for examples, which fits the ESP32-S3&#39;s 512 KB internal RAM and FPU. The training engine is about 250 lines of plain C with no TensorFlow Lite. The hardware is an ESP32-S3 board with 8 MB PSRAM, a 1.28&quot; display, an INMP441 mic and one button (<a href="https://www.youtube.com/watch?v=v4AX5Uz23Go&amp;t=152s" target="_blank" rel="noopener">2:32</a>–<a href="https://www.youtube.com/watch?v=v4AX5Uz23Go&amp;t=210s" target="_blank" rel="noopener">3:30</a>)</li></ul><div class="sh">Demo 1: retraining the signal classifier</div><ul><li><strong>Same accuracy as the laptop:</strong> The board generates its own 4,096 training examples at boot, bit-identical to a Python generator. It goes from about 25% (guessing) to 84.8% test accuracy, exactly what NumPy gets (<a href="https://www.youtube.com/watch?v=v4AX5Uz23Go&amp;t=210s" target="_blank" rel="noopener">3:30</a>–<a href="https://www.youtube.com/watch?v=v4AX5Uz23Go&amp;t=266s" target="_blank" rel="noopener">4:26</a>)</li><li><strong>Speed:</strong> Training takes 35.1 s on one core and 18 s on two (1.95× faster), versus 0.08 s in NumPy on a laptop (about 220× faster). Inference runs at 20,488 decisions/s at 6.9 cycles per multiply-add, versus 36 in Bill&#39;s table. That&#39;s about 5× faster, from compiler speed flags and keeping weights in fast internal RAM, without SIMD (<a href="https://www.youtube.com/watch?v=v4AX5Uz23Go&amp;t=266s" target="_blank" rel="noopener">4:26</a>–<a href="https://www.youtube.com/watch?v=v4AX5Uz23Go&amp;t=344s" target="_blank" rel="noopener">5:44</a>)</li></ul><div class="sh">Demo 2: learning his own sounds</div><ul><li><strong>Trained in 0.9 seconds:</strong> When a sound is louder than the background, the board records half a second and turns it into a 161-number pitch-over-time picture. He recorded 10 examples each of a clap, a finger clap and a table tap, and the board added time shifts and noise. It trained on those 30 examples for 40 rounds in 0.9 s, all on the chip (<a href="https://www.youtube.com/watch?v=v4AX5Uz23Go&amp;t=371s" target="_blank" rel="noopener">6:11</a>–<a href="https://www.youtube.com/watch?v=v4AX5Uz23Go&amp;t=525s" target="_blank" rel="noopener">8:45</a>)</li><li><strong>Results and limits:</strong> It usually identifies the sound with high confidence, but sometimes confuses a clap with a finger clap, since both are short high-frequency bursts. The networks are tiny and the signal processing does a lot of the work. Still, training on-device is practical for small, specific decisions, like a sensor learning what one machine normally sounds like (<a href="https://www.youtube.com/watch?v=v4AX5Uz23Go&amp;t=344s" target="_blank" rel="noopener">5:44</a>–<a href="https://www.youtube.com/watch?v=v4AX5Uz23Go&amp;t=371s" target="_blank" rel="noopener">6:11</a>) (<a href="https://www.youtube.com/watch?v=v4AX5Uz23Go&amp;t=480s" target="_blank" rel="noopener">8:00</a>–<a href="https://www.youtube.com/watch?v=v4AX5Uz23Go&amp;t=607s" target="_blank" rel="noopener">10:07</a>)</li></ul></div></article></div>',1))])}const R=c(b,[["render",_]]);export{z as __pageData,R as default};
